/* Assignments 2, 3, 4 and 6: live controller, clock and process reaper.
 * Arrival processes send atomic hall calls before the tested core advances.
 * Board/exit callbacks serialize capacity semaphore commands by passenger id.
 * The controller alone renders, exports, handles signals and reaps every child. */
#define _DEFAULT_SOURCE
#include "core.h"
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <unistd.h>

typedef struct {Shared*s;Core*c;} Live;
static volatile sig_atomic_t interrupted;
static void stop_now(int sig){(void)sig;interrupted=1;}
static int command(Live*l,int slot,int lift,int cmd){SharedPassenger*p=&l->s->passenger[slot];p->cmd=cmd;p->cmd_lift=lift;p->result=RES_NONE;if(sem_post(&p->go)<0)return-1;if(sem_wait(&p->ack)<0)return-1;return p->result;}
static int live_board(void*ctx,int slot,int lift){return command(ctx,slot,lift,CMD_BOARD)==RES_BOARDED;}
static int live_exit(void*ctx,int slot,int lift){return command(ctx,slot,lift,CMD_EXIT)==RES_EXITED;}
static int read_full(int fd,void*buf,size_t n){size_t got=0;while(got<n){ssize_t r=read(fd,(char*)buf+got,n-got);if(r<0&&errno==EINTR)continue;if(r<=0)return-1;got+=(size_t)r;}return 0;}
static int reqcmp(const void*a,const void*b){const Request*x=a,*y=b;return(x->id>y->id)-(x->id<y->id);}
static void usage(const char*n){printf("Usage: %s --scenario FILE --policy fcfs|nearest [--tick-ms N|--fast] [--no-ui] [--no-sync] [--lazy-reap N] [--out DIR] [--seed N]\n",n);}
static int num(const char*s,int lo,int hi,int*out){char*e;long v=strtol(s,&e,10);if(!*s||*e||v<lo||v>hi)return-1;*out=(int)v;return 0;}
static void summary(const Core*c,const Shared*s){Metrics m;core_metrics(c,&m);puts("\nPassenger results");puts("ID ARR FROM TO BOARD DELIVER LIFT WAIT RIDE TOTAL");for(int i=0;i<c->scenario.passenger_count;i++){const CorePassenger*p=&c->passenger[i];printf("%-2d %-3d %-4d %-2d %-5d %-7d %-4d %-4d %-4d %d\n",p->id,p->arrival,p->from,p->to,p->board_tick,p->deliver_tick,p->lift,p->board_tick-p->arrival,p->deliver_tick-p->board_tick,p->deliver_tick-p->arrival);}printf("Average wait: %.2f\nAverage ride: %.2f\nAverage total: %.2f\nMakespan: %d\nEmpty moves: %.2f%%\nAverage load: %.2f%%\nPreempts: %d\nFull events: %d\nDelivered: %d/%d\nBoard corruption: %lu\n",m.avg_wait,m.avg_ride,m.avg_total,m.makespan,m.empty_move_pct,m.avg_load_pct,m.preempts,m.full_events,m.delivered,c->scenario.passenger_count,s->corrupt);}
int main(int argc,char**argv){const char*path=NULL,*out="out";Policy policy=POLICY_NEAREST;int have_policy=0,tick=-1,no_ui=0,no_sync=0,lazy=0,seed=42;for(int i=1;i<argc;i++){if(!strcmp(argv[i],"--help")){usage(argv[0]);return 0;}else if(!strcmp(argv[i],"--scenario")&&i+1<argc)path=argv[++i];else if(!strcmp(argv[i],"--policy")&&i+1<argc){char*v=argv[++i];if(!strcmp(v,"fcfs"))policy=POLICY_FCFS;else if(!strcmp(v,"nearest"))policy=POLICY_NEAREST;else{fprintf(stderr,"invalid policy\n");return 1;}have_policy=1;}else if(!strcmp(argv[i],"--tick-ms")&&i+1<argc){if(num(argv[++i],1,60000,&tick))return 1;}else if(!strcmp(argv[i],"--fast"))tick=40;else if(!strcmp(argv[i],"--no-ui"))no_ui=1;else if(!strcmp(argv[i],"--no-sync"))no_sync=1;else if(!strcmp(argv[i],"--lazy-reap")&&i+1<argc){if(num(argv[++i],0,10000,&lazy))return 1;}else if(!strcmp(argv[i],"--out")&&i+1<argc)out=argv[++i];else if(!strcmp(argv[i],"--seed")&&i+1<argc){if(num(argv[++i],0,1000000,&seed))return 1;}else{fprintf(stderr,"unknown option %s\n",argv[i]);return 1;}}if(!path||!have_policy){usage(argv[0]);return 1;}Scenario sc;char err[256];if(scenario_load(path,&sc,err,sizeof err)){fprintf(stderr,"Scenario error: %s\n",err);return 1;}if(tick>0)sc.tick_ms=tick;Shared*s=mmap(NULL,sizeof* s,PROT_READ|PROT_WRITE,MAP_SHARED|MAP_ANONYMOUS,-1,0);if(s==MAP_FAILED){perror("mmap");return 2;}memset(s,0,sizeof*s);s->floors=sc.floors;s->lifts=sc.lifts;s->capacity=sc.capacity;s->policy=policy;s->tick_ms=sc.tick_ms;s->passenger_count=sc.passenger_count;s->no_sync=no_sync;if(sem_init(&s->rw_mutex,1,1)<0||sem_init(&s->rw_wrt,1,1)<0){perror("sem_init board");return 2;}for(int k=0;k<sc.lifts;k++){s->lift[k].floor=sc.start[k];s->pos[k]=sc.start[k];if(sem_init(&s->lift[k].cap,1,(unsigned)sc.capacity)<0){perror("sem_init capacity");return 2;}}for(int i=0;i<sc.passenger_count;i++){SharedPassenger*p=&s->passenger[i];p->id=sc.passenger[i].id;p->from=sc.passenger[i].from;p->to=sc.passenger[i].to;p->arrival=sc.passenger[i].arrival;p->state=FUTURE;p->lift=-1;if(sem_init(&p->go,1,0)<0||sem_init(&p->ack,1,0)<0){perror("sem_init passenger");return 2;}}
int fds[2];if(pipe(fds)<0){perror("pipe");return 2;}Core*c=calloc(1,sizeof* c);if(!c){perror("calloc");return 2;}Live live={s,c};if(core_init(c,&sc,policy,(CoreCallbacks){live_board,live_exit,&live})<0)return 2;struct sigaction sa={0};sa.sa_handler=stop_now;sigemptyset(&sa.sa_mask);sigaction(SIGINT,&sa,NULL);sigaction(SIGTERM,&sa,NULL);pid_t pids[MAX_PASSENGERS]={0};int reaped[MAX_PASSENGERS]={0};pid_t controller=getpid();if(!no_ui){printf("\033[?25l");fflush(stdout);}int exit_code=0;
while(c->delivered<sc.passenger_count&&!interrupted){s->tick=c->tick;int slots[MAX_PASSENGERS],nnew=0;for(int i=0;i<sc.passenger_count;i++)if(sc.passenger[i].arrival==c->tick){pid_t q=fork();if(q<0){perror("fork");exit_code=2;interrupted=1;break;}if(q==0){close(fds[0]);passenger_process(s,i,fds[1],controller);_exit(2);}pids[i]=q;s->passenger[i].pid=q;slots[nnew++]=i;}if(interrupted)break;if(nnew){Request req[MAX_PASSENGERS];if(read_full(fds[0],req,(size_t)nnew*sizeof req[0])<0){perror("read requests");exit_code=2;break;}qsort(req,(size_t)nnew,sizeof req[0],reqcmp);for(int j=0;j<nnew;j++){int found=0;for(int x=0;x<nnew;x++)if(req[j].id==sc.passenger[slots[x]].id)found=1;if(!found){fprintf(stderr,"invalid hall call\n");exit_code=2;interrupted=1;break;}}}int before=c->event_count;int r=core_step(c);if(r<0){fprintf(stderr,"ERROR stuck\n");exit_code=2;break;}for(int i=0;i<sc.passenger_count;i++){s->passenger[i].state=c->passenger[i].state;s->passenger[i].lift=c->passenger[i].lift;s->passenger[i].board_tick=c->passenger[i].board_tick;s->passenger[i].deliver_tick=c->passenger[i].deliver_tick;}int pos[MAX_LIFTS],dir[MAX_LIFTS];for(int k=0;k<sc.lifts;k++){pos[k]=c->lift[k].floor;dir[k]=c->lift[k].direction;s->lift[k].floor=pos[k];s->lift[k].riders=c->lift[k].riders;}if(board_write(s,pos,dir)<0){perror("board_write");exit_code=2;break;}if(no_ui)for(int i=before;i<c->event_count;i++){CoreEvent*e=&c->events[i];printf("T=%d EVT=%s P=%d L=%d\n",e->t,e->name,e->passenger,e->lift);}else render_terminal(c,s,lazy);for(int i=0;i<sc.passenger_count;i++)if(pids[i]&&!reaped[i]&&c->passenger[i].state==DONE&&c->tick-c->passenger[i].deliver_tick>lazy){int st;pid_t q=waitpid(pids[i],&st,WNOHANG);if(q==pids[i]){reaped[i]=1;core_event(c,"REAPED",c->passenger[i].id,-1);if(no_ui)printf("T=%d EVT=REAPED P=%d L=-1\n",c->tick,c->passenger[i].id);}else if(q<0&&errno!=EINTR){perror("waitpid");exit_code=2;interrupted=1;break;}}if(sleep_ms(sc.tick_ms)<0){perror("nanosleep");exit_code=2;break;}}
s->done=1;close(fds[0]);close(fds[1]);if(interrupted||exit_code){for(int i=0;i<sc.passenger_count;i++)if(pids[i]&&!reaped[i])kill(pids[i],SIGTERM);}for(int i=0;i<sc.passenger_count;i++)if(pids[i]&&!reaped[i]){int st;while(waitpid(pids[i],&st,0)<0&&errno==EINTR){}reaped[i]=1;if(!interrupted&&!exit_code){core_event(c,"REAPED",c->passenger[i].id,-1);if(no_ui)printf("T=%d EVT=REAPED P=%d L=-1\n",c->tick,c->passenger[i].id);}}if(!no_ui)printf("\033[?25h\n");if(!interrupted&&!exit_code){summary(c,s);if(export_run(c,out,(unsigned)seed)<0){perror("export");exit_code=2;}}for(int i=0;i<sc.passenger_count;i++){sem_destroy(&s->passenger[i].go);sem_destroy(&s->passenger[i].ack);}for(int k=0;k<sc.lifts;k++)sem_destroy(&s->lift[k].cap);sem_destroy(&s->rw_mutex);sem_destroy(&s->rw_wrt);munmap(s,sizeof*s);free(c);return interrupted&&!exit_code?130:exit_code;}
